CREATE OR REPLACE FUNCTION private.base_config() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.org_role_previous_config()||jsonb_build_object('position_slots',c->'position_slots','role_links',c->'role_links','memberships',c->'memberships','units',c->'units','titles',c->'titles') FROM (SELECT private.org_config() c OFFSET 0) snapshot $$;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.role_catalog_change(text,text,text,jsonb,uuid,text,text)'::regprocedure) INTO d; d:=replace(d,$old$proposal:=coalesce(_proposed,'{}');$old$,$new$proposal:=coalesce(_proposed,'{}'); IF _action='create' AND proposal->>'role_kind'='position' AND coalesce(jsonb_array_length(proposal->'permissions'),0)>0 THEN RAISE EXCEPTION 'Role vị trí mới phải có permissions=[]; cấu hình sau khi tạo.'; END IF;$new$); d:=replace(d,$old$affected_:=(SELECT coalesce(jsonb_agg(DISTINCT a.user_id),'[]') FROM org_assignments a JOIN base_title_role_links l ON l.title_id=a.title_id WHERE l.role_id=id_ AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()));$old$,$new$affected_:=(SELECT coalesce(jsonb_agg(DISTINCT user_id),'[]') FROM private.role_source_rows(private.base_config()) WHERE role_id=id_);$new$); EXECUTE d; END $patch$;
CREATE OR REPLACE FUNCTION private.org_slot_permission_scope(u uuid,permission_ text,unit_ text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_active(u) AND private.has_permission(u,permission_) AND EXISTS(SELECT 1 FROM jsonb_array_elements(private.org_slot_rules(u,private.base_config())) r WHERE r->>'permission'=permission_ AND private.base_role_unit_contains(private.base_config(),r->>'unit_id',unit_)) $$;
REVOKE ALL ON FUNCTION private.org_slot_permission_scope(uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;